'use strict';
(function(root){
const keys=['hp','mp','attack','defense','magic','heal','speed','dex'],labels=['HP','MP','攻撃力','守備力','攻撃魔力','回復魔力','すばやさ','きようさ'],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validate(input,master,profile){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('基礎能力の形式が不正です。');const result={};for(const [key,b]of Object.entries(input)){if(!/^[0-3]:job-\d+$/.test(key)||!master.jobs.some(j=>j.id===key.split(':')[1]))throw Error('基礎能力のキャラ・職業を確認してください。');if(!Number.isInteger(b.level)||b.level<1||b.level>95||!Number.isInteger(b.cost)||b.cost<0||b.cost>10000)throw Error('基礎能力のレベル・コストが不正です。');const stats={};for(const k of keys){const v=b.stats?.[k]??(k==='dex'?0:NaN);if(!Number.isInteger(v)||v<0||v>100000)throw Error('基礎能力が不正です：'+k);stats[k]=v;}if(stats.hp<1)throw Error('HPは1以上にしてください。');result[key]={level:b.level,cost:b.cost,stats};}return result;}
function render({target,master,profile,onSave}){target.innerHTML='<p>装備・こころ・心珠・一時的バフを外した状態の能力を、キャラと職業ごとに登録します。永続効果・こころ道などは実測した状態を含めてください。登録時のレベルと現在レベルが違う場合は使いません。</p><div class="character-grid">'+profile.characters.map((c,i)=>'<section class="record-card"><h3>'+esc(c.name)+'</h3><form data-base-member="'+i+'"><label>職業<select name="job">'+master.jobs.map(j=>'<option value="'+j.id+'">'+esc(j.name)+'</option>').join('')+'</select></label><p class="base-level"></p>'+keys.map((k,j)=>'<label>'+labels[j]+'<input name="'+k+'" type="number" min="0" max="100000" step="1" required></label>').join('')+'<label>こころ基本コスト<input name="cost" type="number" min="0" max="10000" required></label><button type="submit">この職業の実測値を保存</button><button type="button" class="base-delete">登録を解除</button><p class="base-status" role="status"></p></form></section>').join('')+'</div>';
 target.querySelectorAll('[data-base-member]').forEach(form=>{const i=Number(form.dataset.baseMember),select=form.elements.job,status=form.querySelector('.base-status');const load=()=>{const id=select.value,lv=profile.characters[i].levels[id]||0,stored=profile.baseOverrides?.[i+':'+id],fallback=master.jobs.find(j=>j.id===id)?.levels[lv];form.querySelector('.base-level').textContent='現在Lv.'+lv+(stored?'／登録Lv.'+stored.level:'／実測値未登録');for(const k of keys)form.elements[k].value=stored?.stats[k]??'';form.elements.cost.value=stored?.cost??fallback?.cost??'';status.textContent=stored&&stored.level!==lv?'レベルが変わったため、再登録するまで仮値を使います。':'';};select.onchange=load;form.onsubmit=e=>{e.preventDefault();try{const id=select.value,level=profile.characters[i].levels[id]||0;if(level<1)throw Error('先に職業レベルを登録してください。');const record={level,cost:Number(form.elements.cost.value),stats:Object.fromEntries(keys.map(k=>[k,Number(form.elements[k].value)]))};profile.baseOverrides=validate({...profile.baseOverrides,[i+':'+id]:record},master,profile);onSave();load();status.textContent='保存しました。統合探索と04の計算に使います。';}catch(e){status.textContent=e.message;}};form.querySelector('.base-delete').onclick=()=>{if(profile.baseOverrides)delete profile.baseOverrides[i+':'+select.value];onSave();load();};load();});}
root.BaseStatsUI={render,validate};
})(typeof window==='undefined'?globalThis:window);
